// ---- src/service/30-install.js
// Installing the launcher build with staged activation (spec §3.2):
//   <DATA>/th08/build/       active build: th08-web.js, th08-web.wasm, the launcher files and
//                            .complete (the VERSION that installed it, written last)
//   <DATA>/th08/staging/     a new build is assembled in staging/build; removed when done,
//                            on error and at every start
//   <DATA>/th08/build.old/   the previous build, only while activating
//   <DATA>/th08/state.json   { buildVersion, buildReady, ... } mirrors build/; later plans
//                            add dataReady and files to it
//   <DATA>/th08/retail/      th08.dat, thbgm.dat (copied from the PC in a later plan)
// The launcher URL, file://<DATA>/th08/build/launcher.html, is the same for every version.

var DOWNLOAD_TIMEOUT_MS = 60000;

// GET into memory, following redirects (GitHub release assets redirect to a CDN). One overall
// deadline per request, and a body cut short (aborted, or shorter than Content-Length) rejects.
function download(url, redirects) {
  redirects = redirects || 0;
  return new Promise(function (resolve, reject) {
    var settled = false, timer = null, req;
    function settle(err, buf) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (err) { req.abort(); reject(err); } else resolve(buf);
    }
    var opts = urlLib.parse(url);
    opts.headers = { 'User-Agent': 'tizenbrew-th08' };
    req = (opts.protocol === 'https:' ? https : http).get(opts, function (res) {
      res.on('error', function (e) { settle(e); });
      res.on('aborted', function () { settle(new Error('connection cut short: ' + url)); });
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        if (redirects >= 5) { settle(new Error('too many redirects: ' + url)); res.destroy(); return; }
        settled = true;
        clearTimeout(timer);
        res.destroy(); // the body is not needed
        return resolve(download(urlLib.resolve(url, res.headers.location), redirects + 1));
      }
      if (res.statusCode !== 200) {
        settle(new Error('HTTP ' + res.statusCode + ' for ' + url));
        return res.destroy(); // the body is not needed
      }
      var chunks = [], got = 0, want = res.headers['content-length'];
      res.on('data', function (c) { chunks.push(c); got += c.length; });
      res.on('end', function () {
        if (want !== undefined && got !== Number(want)) {
          return settle(new Error('got ' + got + ' of ' + want + ' bytes from ' + url));
        }
        settle(null, Buffer.concat(chunks));
      });
    });
    timer = setTimeout(function () {
      settle(new Error('download took longer than ' + DOWNLOAD_TIMEOUT_MS / 1000 + ' s: ' + url));
    }, DOWNLOAD_TIMEOUT_MS);
    req.on('error', function (e) { settle(e); });
  });
}

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

// Regular files of a ustar archive, by path without a leading "./".
function untar(tarBuf) {
  var out = {}, off = 0;
  while (off + 512 <= tarBuf.length) {
    var header = tarBuf.slice(off, off + 512);
    if (header[0] === 0) break;
    var name = header.slice(0, 100).toString('utf8').replace(/\0[\s\S]*$/, '');
    var prefix = header.slice(345, 500).toString('utf8').replace(/\0[\s\S]*$/, '');
    if (prefix) name = prefix + '/' + name;
    var size = parseInt(header.slice(124, 136).toString('ascii').replace(/\0[\s\S]*$/, '').trim() || '0', 8);
    var type = header[156];
    off += 512;
    if (type === 0 || type === 48) out[name.replace(/^\.\//, '')] = tarBuf.slice(off, off + size);
    off += Math.ceil(size / 512) * 512;
  }
  return out;
}

function mkdirp(dir) {
  if (fs.existsSync(dir)) return;
  mkdirp(path.dirname(dir));
  fs.mkdirSync(dir);
}

// rm -rf without fs.rmSync (Node 14.14+), keeping the Node 10.4 floor.
function removeTree(p) {
  var st;
  try { st = fs.lstatSync(p); } catch (e) { return; }
  if (st.isDirectory()) {
    fs.readdirSync(p).forEach(function (name) { removeTree(path.join(p, name)); });
    fs.rmdirSync(p);
  } else {
    fs.unlinkSync(p);
  }
}

function writeAtomic(file, buf) {
  fs.writeFileSync(file + '.part', buf);
  fs.renameSync(file + '.part', file);
}

function readText(file) {
  try { return fs.readFileSync(file, 'utf8'); } catch (e) { return null; }
}

function fileSize(file) {
  try { return fs.statSync(file).size; } catch (e) { return -1; }
}

function readState(root) {
  try { return JSON.parse(fs.readFileSync(path.join(root, 'state.json'), 'utf8')) || {}; } catch (e) { return {}; }
}

// Merges `patch` into state.json, keeping fields this version does not know.
function writeState(root, patch) {
  var state = readState(root);
  Object.keys(patch).forEach(function (k) { state[k] = patch[k]; });
  writeAtomic(path.join(root, 'state.json'), Buffer.from(JSON.stringify(state, null, 2)));
  return state;
}

// The version that installed `dir` if it holds a whole build (marker plus every file
// non-empty), else null.
function buildVersionOf(dir) {
  var marker = readText(path.join(dir, '.complete'));
  if (!marker) return null;
  var names = BUILD_FILES.concat(LAUNCHER_FILES);
  for (var i = 0; i < names.length; i++) {
    if (fileSize(path.join(dir, names[i])) <= 0) return null;
  }
  return marker;
}

// An activation cut short leaves build.old/: keep build/ if it is whole, else put the old
// one back. Leftover staging/ is always removed.
function recover(root) {
  var build = path.join(root, 'build'), old = path.join(root, 'build.old');
  if (fs.existsSync(old)) {
    if (buildVersionOf(build)) {
      removeTree(old);
      log('removed build.old');
    } else {
      removeTree(build);
      fs.renameSync(old, build);
      log('restored build.old');
    }
  }
  removeTree(path.join(root, 'staging'));
}

function syncState(root) {
  var v = buildVersionOf(path.join(root, 'build'));
  return writeState(root, { buildVersion: v, buildReady: v === VERSION });
}

// A service told to stop (a newer one took the port, see 45-takeover.js) must not write
// into <DATA>/th08 any more. Writes are synchronous, so checking before each is enough.
function checkRunning() {
  if (status.state === 'stopped') throw new Error('service stopped');
}

function installBuild(dir) {
  log('download ' + BUILD_URL);
  return download(BUILD_URL).then(function (gz) {
    checkRunning();
    var got = sha256(gz);
    if (got !== BUILD_SHA256) throw new Error('build sha256 mismatch: expected ' + BUILD_SHA256 + ', got ' + got);
    var entries = untar(zlib.gunzipSync(gz));
    BUILD_FILES.forEach(function (name) {
      if (!entries[name] || !entries[name].length) throw new Error('build archive has no (or an empty) ' + name);
      writeAtomic(path.join(dir, name), entries[name]);
    });
  });
}

function installLauncher(dir) {
  return LAUNCHER_FILES.reduce(function (chain, name) {
    return chain.then(function () {
      log('download ' + LAUNCHER_BASE + name);
      return download(LAUNCHER_BASE + name).then(function (buf) {
        checkRunning();
        if (!buf.length) throw new Error('empty download: ' + LAUNCHER_BASE + name);
        writeAtomic(path.join(dir, name), buf);
      });
    });
  }, Promise.resolve());
}

// staging/build → build: (1) build → build.old, (2) staging/build → build, (3) remove
// build.old.
function activate(root) {
  checkRunning();
  var build = path.join(root, 'build'), old = path.join(root, 'build.old');
  if (fs.existsSync(build)) fs.renameSync(build, old);
  fs.renameSync(path.join(root, 'staging', 'build'), build);
  removeTree(old);
  removeTree(path.join(root, 'staging'));
}

// Resolves once build/ holds this version, installing it through staging/ if needed.
function install() {
  checkNode();
  var base = resolveDataDir();
  var root = path.join(base, 'th08');
  status.dataDir = base;
  status.launcherUrl = 'file://' + path.join(root, 'build', 'launcher.html');
  mkdirp(root);
  fileDir = path.join(root, 'retail');
  diskSpace(root).then(function (d) { status.disk = d; });
  recover(root);
  if (syncState(root).buildReady) return Promise.resolve();
  var staged = path.join(root, 'staging', 'build');
  mkdirp(staged);
  status.state = 'installing';
  status.progress = 'th08-web build';
  return installBuild(staged).then(function () {
    status.progress = 'launcher files';
    return installLauncher(staged);
  }).then(function () {
    checkRunning();
    writeAtomic(path.join(staged, '.complete'), Buffer.from(VERSION));
    activate(root);
    syncState(root);
    status.progress = '';
    log('installed build ' + VERSION);
  }).catch(function (e) {
    if (status.state !== 'stopped') removeTree(path.join(root, 'staging'));
    throw e;
  });
}

// ---- src/service/40-devtools.js
// Opening the file:// spike page. Chromium does not let the module page
// (http://127.0.0.1:8081/...) navigate to file:// ("Not allowed to load local resource"),
// but DevTools' Page.navigate may: TizenBrew 2.0.x runs its pages with DevTools open on a
// port of the TV. The ports in LISTEN state are read from /proc/net/tcp*.
function listeningPorts() {
  if (process.env.TH08_DEVTOOLS_PORTS) {
    return process.env.TH08_DEVTOOLS_PORTS.split(',').map(Number);
  }
  var ports = [];
  ['/proc/net/tcp', '/proc/net/tcp6'].forEach(function (file) {
    var lines = (readText(file) || '').split('\n').slice(1);
    lines.forEach(function (line) {
      var cols = line.trim().split(/\s+/);
      if (cols[3] !== '0A') return;      // 0A = LISTEN
      var port = parseInt(cols[1].split(':')[1], 16);
      if (port >= 1024 && port !== PORT && ports.indexOf(port) < 0) ports.push(port);
    });
  });
  return ports;
}

// GET JSON from 127.0.0.1:port. Resolves null on any failure, after 1 s overall, or past 1 MB,
// so one odd listening port cannot stall or crash the DevTools search.
function getJson(port, pathname) {
  return new Promise(function (resolve) {
    var settled = false, req, timer;
    function settle(value) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      req.abort();
      resolve(value);
    }
    req = http.get({ host: '127.0.0.1', port: port, path: pathname }, function (res) {
      var text = '';
      res.setEncoding('utf8');
      res.on('data', function (c) {
        text += c;
        if (text.length > 1048576) settle(null);
      });
      res.on('end', function () {
        var value = null;
        try { value = JSON.parse(text); } catch (e) { value = null; }
        settle(value);
      });
      res.on('error', function () { settle(null); });
      res.on('aborted', function () { settle(null); });
    });
    timer = setTimeout(function () { settle(null); }, 1000);
    req.on('error', function () { settle(null); });
  });
}

function findModulePage() {
  var found = null;
  return Promise.all(listeningPorts().map(function (port) {
    return getJson(port, '/json/list').then(function (list) {
      if (found || !Array.isArray(list)) return;
      list.forEach(function (t) {
        if (!found && t.type === 'page' && String(t.url).indexOf(PAGE_MATCH) >= 0) found = t;
      });
    });
  })).then(function () { return found; });
}

// One CDP call over a minimal WebSocket client (text frames only). Every way out (reply,
// error, close, timeout) goes through settle(), which also tears the connection down.
function cdpCall(wsUrl, method, params) {
  return new Promise(function (resolve, reject) {
    var u = urlLib.parse(wsUrl);
    var socket = null, settled = false;
    var req = http.request({
      host: u.hostname, port: u.port, path: u.path,
      headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13',
                 'Sec-WebSocket-Key': crypto.randomBytes(16).toString('base64') }
    });
    var timer = setTimeout(function () {
      settle(new Error('no answer from DevTools after ' + CDP_TIMEOUT_MS + ' ms'));
    }, CDP_TIMEOUT_MS);
    function settle(err, value) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (socket) socket.destroy();
      else req.abort();
      if (err) reject(err); else resolve(value);
    }
    req.on('error', function (e) { settle(e); });
    req.on('response', function (res) {
      res.resume();
      settle(new Error('DevTools refused the WebSocket: HTTP ' + res.statusCode));
    });
    req.on('upgrade', function (res, sock, head) {
      socket = sock;
      var payload = Buffer.from(JSON.stringify({ id: 1, method: method, params: params }));
      var len = payload.length, header;
      if (len < 126) header = Buffer.from([0x81, 0x80 | len]);
      else { header = Buffer.from([0x81, 0x80 | 126, 0, 0]); header.writeUInt16BE(len, 2); }
      var mask = crypto.randomBytes(4);
      for (var i = 0; i < len; i++) payload[i] ^= mask[i % 4];
      socket.write(Buffer.concat([header, mask, payload]));
      var buf = head && head.length ? head : Buffer.alloc(0);
      function onData(chunk) {
        if (chunk) buf = Buffer.concat([buf, chunk]);
        while (!settled && buf.length >= 2) {
          var n = buf[1] & 0x7f, off = 2;
          if (n === 126) { if (buf.length < 4) return; n = buf.readUInt16BE(2); off = 4; }
          else if (n === 127) { if (buf.length < 10) return; n = buf.readUInt32BE(2) * 4294967296 + buf.readUInt32BE(6); off = 10; }
          if (buf.length < off + n) return;
          var opcode = buf[0] & 0x0f, data = buf.slice(off, off + n);
          buf = buf.slice(off + n);
          if (opcode === 0x8) return settle(new Error('DevTools closed the connection'));
          if (opcode !== 0x1) continue;
          var msg;
          try { msg = JSON.parse(data.toString('utf8')); } catch (e) { continue; }
          if (msg.id === 1) return settle(null, msg);
        }
      }
      socket.on('data', onData);
      socket.on('error', function (e) { settle(e); });
      socket.on('close', function () { settle(new Error('DevTools closed the connection')); });
      onData(null);
    });
    req.end();
  });
}

function openWithDevtools(url) {
  return findModulePage().then(function (page) {
    if (!page) throw new Error('module page not found in DevTools (ports: ' + listeningPorts().join(',') + ')');
    return cdpCall(page.webSocketDebuggerUrl, 'Page.navigate', { url: url });
  }).then(function (msg) {
    if (msg.error) throw new Error('Page.navigate: ' + msg.error.message);
    if (msg.result && msg.result.errorText) throw new Error('Page.navigate: ' + msg.result.errorText);
  });
}

// ---- src/service/50-main.js
var opening = false;

function openLauncher() {
  if (opening) return;
  opening = true;
  status.openError = null;
  log('opening ' + status.launcherUrl);
  Promise.resolve().then(function () { return openWithDevtools(status.launcherUrl); }).then(function () {
    status.openMethod = 'devtools';
    log('opened with DevTools');
  }, function (e) {
    status.openError = e.message;
    log('open failed: ' + e.message);
  }).then(function () { opening = false; });
}

server.on('error', function (e) {
  status.state = 'error';
  status.error = 'port ' + PORT + ': ' + e.message;
});

server.listen(PORT, '127.0.0.1', function () {
  Promise.resolve().then(install).then(function () {
    status.state = 'ready';
    openHandler = openLauncher;
    log('ready');
  }, function (e) {
    status.state = 'error';
    status.error = e.message;
    log('install failed: ' + e.message);
  });
});

module.exports = {
  status: status,
  // TizenBrew from 2.1 opens the URL this returns instead of the module's appPath.
  launchUrl: function () {
    if (status.state !== 'ready') return null;
    status.openMethod = 'launchUrl';
    return status.launcherUrl;
  },
  onStop: function () { server.close(); },
  _test: { parseRange: parseRange, untar: untar, sha256: sha256, diskSpace: diskSpace }
};
